def run_script(script: list, z: int) -> bool:
    """P2PKHに必要な命令だけを実装した簡易Scriptインタプリタ"""
    stack = []
    for op in script:
        if op == "OP_DUP":
            stack.append(stack[-1])
        elif op == "OP_HASH160":
            stack.append(hash160(stack.pop()))
        elif op == "OP_EQUALVERIFY":
            if stack.pop() != stack.pop():
                return False
        elif op == "OP_CHECKSIG":
            pub, sig = stack.pop(), stack.pop()
